const { JSDOM } = await import('jsdom');
const html = process.env.HTML_INPUT;
if (!html) { throw new Error('Missing required input: HTML_INPUT'); }
const dom = new JSDOM(`<div id=\"root\">${html}</div>`);
globalThis.targetElement = dom.window.document.getElementById('root');
globalThis.filename = process.env.FILENAME_INPUT || 'output.pdf';

const mod = await import('react-to-pdf');
const generatePDF = mod.default || mod;
const element = globalThis.targetElement;
const options = { filename: globalThis.filename };
const pdfInstance = await generatePDF(element, options);
if (!pdfInstance || typeof pdfInstance.output !== 'function') { throw new Error('Unexpected PDF instance'); }
const dataUri = pdfInstance.output('datauristring');
const base64 = dataUri.split(',')[1];
globalThis.pdfBase64 = base64;
